"use client";

import Link from "next/link";
import { usePathname, useSearchParams } from "next/navigation";
import SearchBar from "./searchBar";
import { useEffect, useRef } from "react";
import { gsap } from "gsap";

export default function Header() {
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const query = searchParams.toString();

    // 👇 persist block state across renders
    const blockHash = useRef(false);
    const previousHash = useRef("");

    function blockFor(ms: number) {
        blockHash.current = true;
        setTimeout(() => {
            blockHash.current = false;
        }, ms);
    }

    useEffect(() => {
        const updateHash = () => {
            console.log(window.location.hash, previousHash)
            if (window.location.hash === "#cas") {
                const tl1 = gsap.timeline({ defaults: { duration: 1, ease: "power1.out" } });
                
                tl1.to("#headerSearchBar", {
                    opacity: 1,
                    width: "40vw",
                    ease: "easeInOut",
                    duration: 0.2,
                }).to("#headerLabel", {
                    opacity: 0,
                    width: "0",
                    ease: "easeInOut",
                    duration: 0.2,
                    onComplete: () => {
                        (document.querySelector("#headerLabel") as HTMLElement).style.pointerEvents = "none";
                        (document.querySelector("#headerSearchBar") as HTMLElement).style.pointerEvents = "auto";
                    }
                }, "-=0.2");
   
                previousHash.current = window.location.hash;                
            } else if ((previousHash.current === "#cas") && (window.location.hash != "#cas")) {
                const tl2 = gsap.timeline({ defaults: { duration: 1, ease: "power1.out" } });
                
                tl2.to("#headerLabel", {
                    opacity: 1,
                    width: "25vw",
                    ease: "easeInOut",
                    duration: 0.2,
                }).to("#headerSearchBar", {
                    opacity: 0,
                    width: "0",
                    ease: "easeInOut",
                    duration: 0.2,
                    onComplete: () => {
                        (document.querySelector("#headerLabel") as HTMLElement).style.pointerEvents = "auto";
                        (document.querySelector("#headerSearchBar") as HTMLElement).style.pointerEvents = "none";
                    }
                }, "-=0.2");

                previousHash.current = window.location.hash;
            }
        };
        updateHash();

        const sections = document.querySelectorAll("section[id]");
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        if (!blockHash.current) {
                            history.replaceState(null, "", `#${entry.target.id}`);
                        }
                        updateHash();
                    }
                });
            },
            { root: document.querySelector(".scrollContainer"), threshold: 0.6 }
        );

        sections.forEach((section) => observer.observe(section));
        return () => observer.disconnect();
    }, []);

    return (
        <header className="fixed top-0 left-0 w-full h-[7vh] max-h-[90px] lg:max-h-[90px] min-h-[60px] z-50 p-3 flex items-center">
        <Link href={`${pathname}${query ? "?" + query : ""}#home`} onClick={() => blockFor(1000)} className="items-center h-full md:flex cursor-pointer hidden">
            <img src="/logo.svg" alt="logo" className="filter dark:invert h-full" />
        </Link>

        <nav className="flex-1 flex justify-center h-[5vh] items-center text-sm lg:text-lg xl:text-xl 2xl:text-2xl space-x-6 min-h-[50px] max-h-[75px]">
            <Link href={`${pathname}${query ? "?" + query : ""}#home`} onClick={() => blockFor(1000)} className="h-full">
                <div className="flex items-center justify-center h-full w-[25vw] max-w-[100px] rounded-full bubble">
                    Home
                </div>
            </Link>
            <div className="flex items-center justify-center h-full w-fit rounded-full bubble">
                <Link href={`${pathname}${query ? "?" + query : ""}#cas`} className="h-full">
                    <div id="headerLabel" className="flex w-[25vw] max-w-[100px] items-center justify-center h-full w-fullrounded-full">
                        CAS
                    </div>
                </Link>
                <div id="headerSearchBar" className="flex justify-center items-center opacity-0 w-0 pointer-events-none">
                    <SearchBar></SearchBar>
                </div>
            </div>
            <Link href={`${pathname}${query ? "?" + query : ""}#about`} onClick={() => blockFor(1000)} className="h-full">
                <div className="flex items-center justify-center h-full w-[25vw] max-w-[100px] rounded-full bubble">
                    About
                </div>
            </Link>
        </nav>

        <div className="hidden md:flex h-full aspect-square"></div>
        </header>
    );
}